    93	
    94	function WorkspacesListRow({
    95	    title,
    96	    menuItems,
    97	    workspaceIcon,
    98	    fallbackWorkspaceIcon,
    99	    ownerAccountID,
   100	    workspaceType,
   101	    currentUserPersonalDetails,
   102	    layoutWidth = CONST.LAYOUT_WIDTH.NONE,
   103	    rowStyles,
   104	    style,
   105	    brickRoadIndicator,
   106	    shouldDisableThreeDotsMenu,
   107	    isJoinRequestPending,
   108	    policyID,
   109	}: WorkspacesListRowProps) {
