   122	            case CONST.POLICY.TYPE.TEAM:
   123	                return translate('workspace.type.collect');
   124	            default:
   125	                return translate('workspace.type.free');
   126	        }
   127	    }, [workspaceType, translate]);
   128	
   129	    if (layoutWidth === CONST.LAYOUT_WIDTH.NONE) {
   130	        // To prevent layout from jumping or rendering for a split second, when
   131	        // isWide is undefined we don't assume anything and simply return null.
